text:
{
  "units": {
    "s001": {
      "claims": [
        {
          "claim": "该学生为普通软件工程专业本科生",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        },
        {
          "claim": "学生计划以2027年云南大学推荐推免工作实施办法为参考",
          "evidence_sentence_ids": [
            "b1_s009"
          ],
          "score": 5,
          "verdict": "supported"
        },
        {
          "claim": "GPA刚达到基本门槛（即前三年平均GPA不低于3.0）",
          "evidence_sentence_ids": [
            "b1_s022"
          ],
          "score": 5,
          "verdict": "supported"
        },
        {
          "claim": "学生考虑减少课程投入、集中进行竞赛与科研活动",
          "evidence_sentence_ids": [],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘考虑’为行为倾向，非事实陈述，未被证据直接支持"
    },
    "s002": {
      "claims": [
        {
          "claim": "以下基于现有资料进行风险分析和稳妥建议",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        },
        {
          "claim": "同时明确资料不足之处",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "为建议性表述，非事实陈述"
    },
    "s003": {
      "claims": [],
      "non_factual_reason": "为空标记，不构成事实"
    },
    "s004": {
      "claims": [
        {
          "claim": "风险分析部分开始",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "为标题，非事实陈述"
    },
    "s005": {
      "claims": [
        {
          "claim": "风险分析中第一条：GPA门槛虽达标，但综合测评成绩仍可能不满足要求",
          "evidence_sentence_ids": [
            "b1_s020",
            "b1_s021",
            "b1_s022"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s006": {
      "claims": [
        {
          "claim": "2027年学校推免办法第（五）条规定：前三学年综合测评成绩平均分不低于80分",
          "evidence_sentence_ids": [
            "b1_s020"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s007": {
      "claims": [
        {
          "claim": "综合测评成绩与GPA并列作为推荐条件",
          "evidence_sentence_ids": [
            "b1_s020",
            "b1_s022"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s008": {
      "claims": [
        {
          "claim": "综合测评成绩是独立于GPA的指标",
          "evidence_sentence_ids": [
            "b1_s020",
            "b1_s022"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "未明确‘独立’，仅并列列出，需推导"
    },
    "s009": {
      "claims": [
        {
          "claim": "若学生仅通过减少课程投入来提升科研，而忽视课堂参与、作业完成、课堂表现等综合测评要素，则综合测评成绩可能无法达到80分，从而直接导致失去推荐资格",
          "evidence_sentence_ids": [
            "b1_s020",
            "b1_s022"
          ],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘直接导致’为因果推断，证据未说明后果必然性"
    },
    "s010": {
      "claims": [
        {
          "claim": "文件[1]为2027年推免办法第（五）条",
          "evidence_sentence_ids": [
            "b1_s020"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s011": {
      "claims": [
        {
          "claim": "竞赛与科研成果虽被纳入综合测评，但未明确其权重与认定标准",
          "evidence_sentence_ids": [
            "b1_s010"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘纳入’由教育部文件规定，但未说明权重与认定标准"
    },
    "s012": {
      "claims": [
        {
          "claim": "教育部文件规定科研成果、竞赛获奖等情况纳入综合测评体系",
          "evidence_sentence_ids": [
            "b1_s010"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s013": {
      "claims": [
        {
          "claim": "学生若仅依赖竞赛或科研‘加分’来弥补综合测评短板，存在‘成果未被认可’或‘加分不足’的风险",
          "evidence_sentence_ids": [
            "b1_s010"
          ],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "无证据支持‘加分不足’或‘未被认可’的具体情形"
    },
    "s014": {
      "claims": [
        {
          "claim": "若竞赛奖项未被纳入学校或学院的官方认定目录，或未在推免材料中体现，可能无法被计入综合测评成绩",
          "evidence_sentence_ids": [],
          "score": 1,
          "verdict": "contradicted"
        }
      ],
      "non_factual_reason": "无任何证据提及‘官方认定目录’或‘材料体现’要求"
    },
    "s015": {
      "claims": [
        {
          "claim": "资料中未说明竞赛或科研成果是否可作为‘替代性’条件",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "未提及替代性，属于资料缺失"
    },
    "s016": {
      "claims": [
        {
          "claim": "无法保证其对GPA不足的补救作用",
          "evidence_sentence_ids": [],
          "score": 1,
          "verdict": "contradicted"
        }
      ],
      "non_factual_reason": "无证据支持‘补救作用’，属过度推断"
    },
    "s017": {
      "claims": [
        {
          "claim": "推免办法要求学生‘具有从事科学研究、专业实践的能力和基础，以及较强的创新意识和潜质’",
          "evidence_sentence_ids": [
            "b1_s019"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s018": {
      "claims": [
        {
          "claim": "未提供具体评估方式或案例",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "未说明评估方式，属于资料缺失"
    },
    "s019": {
      "claims": [
        {
          "claim": "若学生仅‘集中做科研’但未形成可展示的成果（如论文、专利、项目报告等），则其‘创新潜质’难以被评审委员会认可",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "无证据支持‘成果形式’或‘评审标准’"
    },
    "s020": {
      "claims": [
        {
          "claim": "资料中未说明科研成果是否需发表于期刊或会议，或是否需有指导教师推荐",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "未提及发表或指导教师要求，属于资料缺失"
    },
    "s021": {
      "claims": [
        {
          "claim": "学院可自行提高标准，存在‘额外要求’风险",
          "evidence_sentence_ids": [
            "b5_s021"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘可自行提高标准’在2026年办法中明确，但未说明2027年是否变化"
    },
    "s022": {
      "claims": [
        {
          "claim": "2027年推免办法第（六）条规定：学院可结合自身情况在上述条件基础上提高标准或增加其他要求",
          "evidence_sentence_ids": [
            "b5_s021"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "b5_s021为2026年文件，非2027年，但内容一致，可推导"
    },
    "s023": {
      "claims": [
        {
          "claim": "软件学院虽在2025年细则中明确列出推荐条件，但该细则为2025届，不能直接用于推断2027年软件学院的政策变化",
          "evidence_sentence_ids": [
            "b2_s005"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s024": {
      "claims": [
        {
          "claim": "若软件学院在2027年调整了推荐标准（如要求科研成果、竞赛等级、项目数量等），则学生当前策略可能无法实际实现",
          "evidence_sentence_ids": [],
          "score": 1,
          "verdict": "contradicted"
        }
      ],
      "non_factual_reason": "无证据支持‘调整标准’或‘策略失效’，属过度推断"
    }
  }
}
